ns.LANGUAGES = {
  { "auto", nil }, { "deDE", "Deutsch" }, { "enUS", "English (US)" }, { "enGB", "English (UK)" },
  { "frFR", "Français" }, { "esES", "Español (EU)" }, { "esMX", "Español (AL)" }, { "itIT", "Italiano" },
  { "ptBR", "Português" }, { "ruRU", "Русский" }, { "koKR", "한국어" }, { "zhCN", "简体中文" }, { "zhTW", "繁體中文" },
}

ns.L = setmetatable({}, { __index = function(_, k) return LOCALES.enUS[k] or k end })

function ns.ApplyLocale(code)
  if not code or code == "auto" then code = (GetLocale and GetLocale()) or "enUS" end
  local active = LOCALES[code] or LOCALES.enUS
  ns.activeLocale = code
  setmetatable(ns.L, { __index = function(_, k) return active[k] or LOCALES.enUS[k] or k end })
end

ns._LOCALES = LOCALES
